                                var date_from_string = function (str) {
                                    var months = ["jan", "feb", "mar", "apr", "may", "jun", "jul",
                                                    "aug", "sep", "oct", "nov", "dec"];
                                    var pattern = "^([a-zA-Z]{3})\\s*(\\d{2}),\\s*(\\d{4})$";
                                    var re = new RegExp(pattern);
                                    var DateParts = re.exec(str).slice(1);

                                    var Year = DateParts[2];
                                    var Month = $.inArray(DateParts[0].toLowerCase(), months);
                                    var Day = DateParts[1];
                                    return new Date(Year, Month, Day);
                                }

                                var moveBlanks = function (a, b) {

                                    if (a < b) {
                                        if (a == "")
                                            return 1;
                                        else
                                            return -1;
                                    }
                                    if (a > b) {
                                        if (b == "")
                                            return -1;
                                        else
                                            return 1;
                                    }
                                    return 0;
                                };
                                var moveBlanksDesc = function (a, b) {
                                    // Blanks are by definition the smallest value, so we don't have to
                                    // worry about them here
                                    if (a < b)
                                        return 1;
                                    if (a > b)
                                        return -1;
                                    return 0;
                                };

                                var table = $("table").stupidtable({

                                    "date": function (a, b) {
                                        // Get these into date objects for comparison.

                                        aDate = new Date(a);
                                        bDate = new Date(b);

                                        return aDate - bDate;
                                    },
                                    "moveBlanks": moveBlanks,
                                    "moveBlanksDesc": moveBlanksDesc,
                                    "accounting": function (a, b) {
                                        if (CDec2(a) < CDec2(b))
                                            return 1;
                                        if (CDec2(a) > CDec2(b))
                                            return -1;
                                        return 0;
                                    },
                                    "percentage": function (a, b) {
                                        var vA = a.replace('%', '');
                                        var vB = b.replace('%', '');
                                        if (CDec2(vA) < CDec2(vB))
                                            return 1;
                                        if (CDec2(vA) > CDec2(vB))
                                            return -1;
                                        return 0;
                                    }
                                });

                                table.on("beforetablesort", function (event, data) {
                                    // data.column - the index of the column sorted after a click
                                    // data.direction - the sorting direction (either asc or desc)
                                    $("#msg").text("Sorting index " + data.column)
                                    $(this).find('tbody').find('tr').each(function () {
                                        $(this).find("td:eq(" + data.column + ")").find('b').detach();
                                    })
                                });

                                table.on("aftertablesort", function (event, data) {

                                    var th = $(this).find("th");
                                    th.find(".arrow").remove();
                                    var dir = $.fn.stupidtable.dir;

                                    var arrow = data.direction === dir.ASC ? "&uarr;" : "&darr;";
                                    th.eq(data.column).append('<span class="arrow">' + arrow + '</span>');

                                    try {
                                        $(this)//.table();
                                    }
                                    catch (e) {
                                        $(this)//.table()//.table('refresh');
                                    }
                                });

