                                    $('#btnDeviceMonitoring').click(function () {

                                        //PromptUserAccess('Allow Special Discount Report', {
                                        //    OnClickOKSuccess: function () {
                                        function HideDeviceMonitoringFilters(vRows) {
                                            for (var i in vRows) {
                                                $.grep(devicemonitoringfilters, function (e, index) {
                                                    if (e.ModuleName == vRows[i].ModuleName) {
                                                        $('option[value="' + e.Value +'"]').remove();
                                                    }
                                                })
                                            }

                                            sessionStorage.SelectedGroup = '';
                                            sessionStorage.SelectedFOWSTName = '';

                                            AddBreadCrumb({
                                                ClearNav: true,
                                                text: 'Device Monitoring', Click: function () {
                                                    $('#divDeviceMonitoring').pageshow();
                                                }
                                            }, '.ItemsBreadCrumbs')
                                            $('#divDeviceMonitoring').pageshow();

                                            //if (CStr2(sessionStorage.SelectedFOWST) != '') {
                                            //    $('.lblSpecialDiscountReportFOWST').text(sessionStorage.SelectedFOWSTName);
                                            //}

                                            if (CStr2(sessionStorage.SelectedGroup) != '') {

                                                $('#btnDeviceMonitoringGroupFOWST').text(sessionStorage.SelectedGroupName);
                                            }

                                            $('#popupDeviceStatus .modal-body > div').appendTo('#dvDeviceAvailability');
                                            $('#tblDeviceAvailability tbody').empty();
                                        }

                                        if (IsMobile) {
                                            var vRows = Sql.Execute(" SELECT md.ModuleName, rmd.IshasAccess as IsHidden, md.SortOrder \n" +
                                                " FROM LibrarySecurityRoleUser usr \n" +
                                                " INNER JOIN LibrarySecurityRole r ON (usr.RoleID = r.ID) \n" +
                                                " INNER JOIN LibrarySecurityRoleModules rmd ON (rmd.RoleID = r.ID) \n" +
                                                " INNER JOIN LibrarySecurityModule md ON (rmd.ModuleID = md.ID) \n" +
                                                " WHERE rmd.IshasAccess = 1 \n" +
                                                " AND usr.PeopleID = " + ReadyString(sessionStorage.PeopleID) + " \n" +
                                                " AND (md.ID = 'c14d332d-9103-4fe0-b6b9-cc0c404637ed' OR md.HeaderID = 'c14d332d-9103-4fe0-b6b9-cc0c404637ed') \n" +
                                                " ORDER BY SortOrder ASC \n").Rows;

                                            HideDeviceMonitoringFilters(vRows);
                                        } else {
                                            AjaxSend({
                                                url: '/DashboardsAndReports/DeviceMonitoringFilters',
                                                success: function (e) {
                                                    var vRows = e.Results.Rows;

                                                    HideDeviceMonitoringFilters(vRows);
                                                }
                                            })
                                        }
                                         //   }
                                        //});
                                    })                                                                       

