                            //========================================== Hourly Sales Report=====================================
                            var mHourlySalesReport;
                            var mHourlySalesReportFrom;
                            var mHourlySalesReportTo;

                            function GetHourlySalesReport() {
                                //if (vDate.trim() == 'Today') {
                                //    vDate = new Date();
                                //}

                                if (CStr2(mSalesReportFrom) == '' || CStr2(mSalesReportTo) == '') {
                                    return;
                                }


                                if (CStr2(sessionStorage.SelectedFOWST) == '' && CStr2(sessionStorage.SelectedGroup) == '') {
                                    return;
                                }

                                var data = {
                                    dateFrom: mSalesReportFrom,
                                    dateTo: mSalesReportTo,
                                    FOWSTID: sessionStorage.SelectedFOWST,
                                    GroupFOWSTID: sessionStorage.SelectedGroup,
                                    StoreType: $('#selHourlySalesReportStoreType').val(),
                                    StoreLocationType: $('#selHourlySalesReportStoreLocationType').val()
                                }

                                AjaxSend({
                                    url: 'CincoCorporation/GetHourlySalesReport',
                                    data: data,
                                    success: function (vData) {

                                        DisplayHourlySalesReport(vData.Results.Rows);

                                    }
                                });
                            }

                            function DisplayHourlySalesReport(vRows) {
                                var totalProductCount = 0;
                                var totalTransactionCount = 0;
                                var totalNetSales = 0;

                                if ($.fn.DataTable.isDataTable($('#tblHourlySalesReport'))) {
                                    $('#tblHourlySalesReport').empty();
                                    try {
                                        mHourlySalesReport.destroy();
                                    } catch (e) {

                                    }                                    
                                }

                                for (var i = 0; i < vRows.length - 1; i++) {
                                    totalProductCount += CDec2(vRows[i].ItemCount);
                                    totalTransactionCount += CDec2(vRows[i].TransactionCount);
                                    totalNetSales += (CDec2(vRows[i].GrossSales) - CDec2(vRows[i].Discount) - CDec2(vRows[i].SalesReturn))
                                }

                                var buttons = [];
                                if (!IsMobile) {
                                    buttons.push({ extend: 'csvHtml5', text: 'Download CSV', title: 'Hourly Sales' })
                                }

                                mHourlySalesReport = $('#tblHourlySalesReport').DataTable({
                                    pageLength: 25,
                                    "ordering": false,
                                    "data": vRows,
                                    "columns": [
                                        {
                                            "data": function (data) {
                                                var mHour = new Date();
                                                mHour.setHours(CInt2(data.HourOfDayInInteger));

                                                return $.format.date(mHour, 'hh:00 a');
                                            }
                                        },
                                        { "data": "ItemCount" },
                                        {
                                            "data": function (data) {
                                                var total = AccountingFormat(CDec2(data.ItemCount) / totalProductCount * 100);

                                                if (total > 0) return total + '%';
                                                else return total;
                                            }
                                        },
                                        { "data": "TransactionCount" },
                                        {
                                            "data": function (data) {
                                                var total = AccountingFormat(CDec2(data.TransactionCount) / totalTransactionCount * 100);

                                                if (total > 0) return total + '%';
                                                else return total;
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                return AccountingFormat(CDec2(data.GrossSales) - CDec2(data.Discount) - CDec2(data.SalesReturn));
                                                //'PhP ' + gitanggal kay mag-error pagcompute sa footer
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                var total = AccountingFormat((CDec2(data.GrossSales) - CDec2(data.Discount) - CDec2(data.SalesReturn)) / totalNetSales * 100);

                                                if (total > 0) return total + '%';
                                                else return total;
                                            }
                                        },
                                    ],                                    
                                    dom: 'Brtip',
                                    buttons: buttons,
                                    initComplete: function () {
                                        $('#tblHourlySalesReport').removeClass('dataTable');
                                    },
                                    footerCallback: function (row, data, start, end, display) {
                                        var api = this.api(), data;

                                        // Remove the formatting to get integer data for summation
                                        var intVal = function (i) {
                                            return typeof i === 'string' ?
                                                i.replace(/[\$,]/g, '') * 1 :
                                                typeof i === 'number' ?
                                                i : 0;
                                        };
                                        for (i = 1; i <= 6; i++) {
                                            // Total over all pages
                                            total = api
                                                .column(i)
                                                .data()
                                                .reduce(function (a, b) {
                                                    return intVal(CDec2(a)) + intVal(CDec2(b));
                                                }, 0);

                                            // Total over this page
                                            pageTotal = api
                                                .column(i, { page: 'current' })
                                                .data()
                                                .reduce(function (a, b) {
                                                    return intVal(CDec2(a)) + intVal(CDec2(b));
                                                }, 0);

                                            // Update footer
                                            if (i == 2 || i == 4 || i == 6) {
                                                $(api.column(i).footer()).html(
                                                   '100%'
                                               ); 
                                            } else {
                                                $(api.column(i).footer()).html(
                                                    AccountingFormat(total)
                                                );
                                            } 
                                        }
                                    }
                                });

                                mHourlySalesReport.on('click', 'td', function () {
                                    var data = mHourlySalesReport.row(this).data();

                                });
                            }

