                            //========================================== Inventory Movement =====================================

                            var mInventoryMovement;
                            var mInventoryMovementFrom;
                            var mInventoryMovementTo;

                            function GetInventoryMovement() {
                                
                                if (CStr2(mSalesReportFrom) == '' || CStr2(mSalesReportTo) == '') {
                                    return;
                                }

                                if (CStr2(sessionStorage.SelectedFOWST) == '') {
                                    return;
                                }

                                var data = {
                                    dateFrom: mSalesReportFrom,
                                    dateTo: mSalesReportTo,
                                    FOWSTID: sessionStorage.SelectedFOWST
                                }
                                Bs.Loading('show');
                                AjaxSend({
                                    url: 'CincoCorporation/GetInventoryMovement',
                                    data: data,
                                    success: function (vData) {

                                        DisplayInventoryMovement(vData.Results.Rows);

                                    }
                                });
                            }

                            function DisplayInventoryMovement(vRows) {
                                if ($.fn.DataTable.isDataTable($('#tblInventoryMovementReport'))) {
                                    $('#tblInventoryMovementReport').empty();
                                    try {
                                        mInventoryMovement.destroy();
                                    } catch (e) {

                                    }                                    
                                }

                                var buttons = [];
                                if (!IsMobile) {
                                    buttons.push({ extend: 'csvHtml5', text: 'Download CSV', title: 'Inventory Movement' })
                                }

                                mInventoryMovement = $('#tblInventoryMovementReport').DataTable({
                                    pageLength: 25,
                                    "ordering": false,
                                    "data": vRows,
                                    "columns": [
                                        { "data": "ProductName" },                                        
                                        { "data": "UnitMeasure" },
                                        {
                                            "data": function (data) {
                                                return AccountingFormat(CDec2(data.Balance));
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                return AccountingFormat(CDec2(data.Delivery));
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                return AccountingFormat(CDec2(data.TransIn));
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                return AccountingFormat(CDec2(data.TransOut));
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                return AccountingFormat(CDec2(data.Shortlanded));
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                return AccountingFormat(CDec2(data.Usage) * -1);
                                            }
                                        },                                       
                                        {
                                            "data": function (data) {
                                                return AccountingFormat(CDec2(data.Ending));
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                return AccountingFormat(CDec2(data.Variance) * -1);
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                return AccountingFormat(CDec2(data.InventoryCount));
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                if(CDec2(data.InventoryCount)>0){
                                                    return AccountingFormat(CDec2(data.InventoryCount)-(CDec2(data.Variance) * -1));
                                                }else{
                                                    return AccountingFormat(CDec2(data.Ending));
                                                }
                                                
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                return AccountingFormat(CDec2(data.Cost));
                                            }
                                        },
                                        {
                                            //total cost
                                            "data": function (data) {
                                                return AccountingFormat((CDec2(data.Usage) * -1) * CDec2(data.Cost));
                                            }
                                        },
                                        {
                                            //Net of VAT - total Cost
                                            "data": function (data) {
                                                return AccountingFormat(((CDec2(data.Usage) * -1) * CDec2(data.Cost))/1.12);
                                            }
                                        }
                                    ],
                                    dom: 'Brtip',
                                    buttons: buttons,
                                    initComplete: function () {
                                        Bs.Loading('hide');
                                        $('#tblInventoryMovementReport').removeClass('dataTable');
                                    },
                                    "rowCallback": function (row, data, displayNum, displayIndex, dataIndex) {
                                        $(row)
                                            .data('data', data)
                                            .click(function (e) {
                                                e.stopPropagation();
                                                var data = $(this).data('data');
                                                sessionStorage.IsFromInventoryBalance = true;
                                                sessionStorage.InventoryBalanceProductID = data.ProductID;
                                                sessionStorage.InventoryBalanceProductName = data.ProductName;                                                
                                                InventoryLedger.Page(false, function () {
                                                    if (typeof InventoryLedger.CheckSource != 'undefined') InventoryLedger.CheckSource();
                                                });
                                            })
                                    }
                                });
                            }

