                                            Bs.Loading('show');
                                            AjaxSend({
                                                url: '/CincoCorporation/GetSpecialPromoReportDetails',
                                                data: {
                                                    dateFrom: $.format.date(new Date(rowData.Invoicedate), 'MM-dd-yyyy'),
                                                    dateTo: $.format.date(new Date(rowData.Invoicedate), 'MM-dd-yyyy'),
                                                    FOWSTID: rowData.FowstID,
                                                    ProductID: rowData.ProductID
                                                }, success: function (e) {
                                                    Bs.Loading('hide');

                                                    var vRows = e.Results.Rows;
                                                    var tblSpecialPromoDetails = $('#tblSpecialPromoDetails tbody').empty();

                                                    for (var i = 0 in vRows) {
                                                        tblSpecialPromoDetails.append($('<tr>')
                                                            .append('<td>' + (CInt2(i) + 1) + '.</td>')
                                                            .append('<td>' + vRows[i].InvoiceNumber + '</td>')
                                                            .append('<td class="text-center">' + $.format.date(new Date(vRows[i].InvoiceDate), 'MM-dd-yyyy') +'</td>')
                                                            .append('<td class="text-center">' + $.format.date(new Date(vRows[i].InvoiceDate), 'hh:mm a') + '</td>')
                                                            .append('<td>' + vRows[i].FowstName + '</td>')
                                                            .append('<td>' + CStr2(vRows[i].EmployeeNoUsed) +'</td>')
                                                            .append('<td>' + vRows[i].ProductName + '</td>')
                                                            .append('<td class="text-center">' + CInt2(vRows[i].Quantity) + '</td>')
                                                            .append('<td class="text-center">' + AccountingFormat(vRows[i].SubTotal) + '</td>')
                                                            .append('<td>' + vRows[i].ModeOfPayment +'</td>')
                                                        )
                                                    }

                                                    $('#lblSPStoreName').text(rowData.StoreName);
                                                    $('#lblSPPromo').text(rowData.Promo);
                                                    $('#popupSpecialPromo').modal('show');
                                                }
                                            })
