                            var mProductPerformanceTrackerReport = '';
                            var mProductPerformanceTrackerNonFlavorReport = '';
                            var mProductPerformanceTrackerReportFrom = '';
                            var mProductPerformanceTrackerReportTo = '';


                            function GetProductPerformanceTrackerReport() {
                                var StoreType = '';
                                                                
                                if (CStr2(mSalesReportFrom) == '' || CStr2(mSalesReportTo) == '') {
                                    return;
                                }

                                if($('#selStoreTypeProductPerformanceTracker').val()=='optCompanyOwnedStores'){
                                    StoreType = 'Company-Owned';
                                }else{
                                    StoreType = 'Franchisee';
                                }

                                var data = {
                                    dateFrom: mSalesReportFrom,
                                    dateTo: mSalesReportTo,
                                    FOWSTID: sessionStorage.SelectedFOWST,
                                    GroupID: sessionStorage.SelectedGroup,
                                    ByProduct: CInt2(sessionStorage.ByProduct),
                                    SelectedProductID: sessionStorage.SelectedProductID,
                                    StoreType: StoreType
                                }

                                Bs.Loading('show');

                                if(CInt2(sessionStorage.ByProduct)==2){
                                    AjaxSend({
                                        timeout: 300000,// 5 minutes
                                        url: 'CincoCorporation/ProductPerformanceTrackerComboMix',
                                        data: data,
                                        success: function (vData) {

                                            DisplayProductPerformanceTrackerReport(vData.Results.Rows, vData.Results.Columns);
                                            Bs.Loading('hide');
                                        }
                                    });
                                }else{
                                    AjaxSend({
                                        timeout: 300000,// 5 minutes
                                        url: 'CincoCorporation/ProductPerformanceTracker',
                                        data: data,
                                        success: function (vData) {

                                            DisplayProductPerformanceTrackerReport(vData.Results.Rows, vData.Results.Columns);
                                            Bs.Loading('hide');
                                        }
                                    });
                                }
                                
                            }

                            function DisplayProductPerformanceTrackerReport(vRows, vColumns) {
                                var columns = [];

                                if (!CBool(sessionStorage.ByProduct)) {

                                    $('#dvProductPerformanceTrackerReport').css('visibility', 'visible');
                                    $('#dvProductPerformanceTrackerReport').css('display', 'block');

                                    $('#dvProductPerformanceTrackerNonFlavorReport').css('visibility', 'hidden');
                                    $('#dvProductPerformanceTrackerNonFlavorReport').css('display', 'none');

                                    if ($.fn.DataTable.isDataTable($('#tblProductPerformanceTrackerReport'))) {                                        
                                        mProductPerformanceTrackerReport.destroy();                                        
                                        $('#tblProductPerformanceTrackerReport').empty();
                                    }                                    

                                    var buttons = [];
                                    if (!IsMobile) {
                                        buttons.push({ extend: 'csvHtml5', text: 'Download CSV', title: 'Performance Tracker Report-Flavor' })
                                    }

                                    var columnNames = Object.keys(vColumns);

                                    for (var i in columnNames) {
                                        columns.push({
                                            data: columnNames[i],
                                            title: columnNames[i]
                                        });
                                    }

                                    for (x = 0; x <= vRows.length - 1; x++) {
                                        for (var i = 2; i <= columns.length - 1; i++) {
                                            if (vRows[x][columns[i].title] == undefined) {
                                                vRows[x][columns[i].title] = AccountingFormat(0)
                                            } else {
                                                vRows[x][columns[i].title] = AccountingFormat(vRows[x][columns[i].title])
                                            }
                                        }
                                    }

                                    mProductPerformanceTrackerReport = $('#tblProductPerformanceTrackerReport').DataTable({
                                        pageLength: 25,
                                        "ordering": false,
                                        "data": vRows,
                                        columns: columns,
                                        dom: 'Brtip',
                                        buttons: buttons,
                                        initComplete: function () {
                                            $('#tblProductPerformanceTrackerReport').removeClass('dataTable');
                                        }
                                    });

                                    mProductPerformanceTrackerReport.on('click', 'td', function () {

                                    });

                                } else { //finished products

                                    $('#dvProductPerformanceTrackerNonFlavorReport').css('visibility', 'visible');
                                    $('#dvProductPerformanceTrackerNonFlavorReport').css('display', 'block');
                                    
                                    $('#dvProductPerformanceTrackerReport').css('visibility', 'hidden');
                                    $('#dvProductPerformanceTrackerReport').css('display', 'none');

                                    if ($.fn.DataTable.isDataTable($('#tblProductPerformanceTrackerNonFlavorReport'))) {                                        
                                        mProductPerformanceTrackerNonFlavorReport.destroy();
                                        $('#tblProductPerformanceTrackerNonFlavorReport').empty();
                                    }

                                    var buttons = [];
                                    if (!IsMobile) {
                                        buttons.push({ extend: 'csvHtml5', text: 'Download CSV', title: 'Performance Tracker Report-Finished Products' })
                                    }

                                    var columnNames = Object.keys(vColumns);

                                    for (var i in columnNames) {
                                        columns.push({
                                            data: columnNames[i],
                                            title: columnNames[i]
                                        });
                                    }

                                    for (x = 0; x <= vRows.length - 1; x++) {
                                        for (var i = 2; i <= columns.length - 1; i++) {
                                            if (vRows[x][columns[i].title] == undefined) {
                                                vRows[x][columns[i].title] = AccountingFormat(0)
                                            } else {
                                                vRows[x][columns[i].title] = AccountingFormat(vRows[x][columns[i].title])
                                            }
                                        }
                                    }

                                    mProductPerformanceTrackerNonFlavorReport = $('#tblProductPerformanceTrackerNonFlavorReport').DataTable({
                                        pageLength: 25,
                                        "ordering": false,
                                        "data": vRows,
                                        columns: columns,
                                        dom: 'Brtip',
                                        buttons: buttons,
                                        initComplete: function () {
                                            $('#tblProductPerformanceTrackerNonFlavorReport').removeClass('dataTable');
                                        }
                                    });

                                    mProductPerformanceTrackerNonFlavorReport.on('click', 'td', function () {

                                    });
                                }
                            }
                            //========================================== End of Product Performance Tracker Report =====================================

