                            var mConsolidatedUsageperDayTo = '';


                            function GetConsolidatedUsageperDay(ReportType) {

                                var data = {                                    
                                    FOWSTID: sessionStorage.SelectedFOWST,
                                    GroupID: sessionStorage.SelectedGroup,
                                    ReportType: ReportType
                                }

                                if (CStr2(mSalesReportFrom) == '' || CStr2(mSalesReportTo) == '') {
                                    return;
                                }

                                data.dateFrom = mSalesReportFrom;
                                data.dateTo = mSalesReportTo;


                                if (CStr2(sessionStorage.SelectedFOWST) == '' && CStr2(sessionStorage.SelectedGroup) == '') {
                                    return;
                                }
                              

                                AjaxSend({
                                    url: 'CincoCorporation/GetConsumptionReportPerType',
                                    data: data,
                                    success: function (vData) {

                                        if (ReportType == 'Usage') {
                                            DisplayConsolidatedUsageperDay(vData.Results.Rows, vData.Results.Columns);
                                        } else {
                                            DisplayConsolidatedEndingBalanceperDay(vData.Results.Rows, vData.Results.Columns);
                                        }
                                    }
                                });
                            }

