                            //========================================== Sales Summary Report =====================================
                            var mSalesSummaryReport;
                            var mSalesSummaryReportFrom;
                            var mSalesSummaryReportTo;

                            function GetSalesSummaryReport() {
                              
                                if (CStr2(mSalesReportFrom) == '' || CStr2(mSalesReportTo) == '') {
                                    return;
                                }
                                
                                if (CStr2(sessionStorage.SelectedFOWST) == '' && CStr2(sessionStorage.SelectedGroup) == '') {
                                    return;
                                }
                                
                                var data = {
                                    dateFrom: mSalesReportFrom,
                                    dateTo: mSalesReportTo,
                                    FOWSTID: sessionStorage.SelectedFOWST,
                                    GroupID: sessionStorage.SelectedGroup,
                                    StoreType: $('#selDailySalesReportStoreType').val(),
                                    StoreLocationType: $('#selDailySalesReportStoreLocationType').val()
                                }

                                Bs.Loading('show');

                                AjaxSend({
                                    url: 'CincoCorporation/GetSalesSummaryReport',
                                    data: data,
                                    success: function (vData) {

                                        Bs.Loading('hide');
                                        DisplaySalesSummaryReport(vData.Results.Rows);
                                                                                
                                    }
                                });
                            }

                            function DisplaySalesSummaryReport(vRows) {
                                                                
                                if ($.fn.DataTable.isDataTable($('#tblSalesSummaryReport'))) {
                                    $('#tblSalesSummaryReport').empty();
                                    try {
                                        mSalesSummaryReport.destroy();
                                    } catch (e) {

                                    }                                    
                                }

                                var buttons = [];
                                if (!IsMobile) {
                                    buttons.push({ extend: 'csvHtml5', text: 'Download CSV', title: 'Sales Report' })
                                }
                                
                                mSalesSummaryReport = $('#tblSalesSummaryReport').DataTable({
                                    pageLength: 25,
                                    "ordering": false,
                                    "data": vRows,
                                    "columns": [
                                        {
                                            "data": function (data) {
                                                return $.format.date(new Date(data.TransactionDate), 'MMM dd, yyyy')
                                            }
                                        },
                                        { "data": "FOWSTCode" },
                                        { "data": "FOWSTName" },
                                        {
                                            "data": function (data) {                                                
                                                if(data.GroupName.includes('CO')){
                                                    return 'CO';
                                                }else{
                                                    return 'FO';
                                                }                                                              
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                return data.GroupName.replace('CO - ','').replace('FO - ','');                                
                                            }
                                        },                                        
                                        { "data": "StoreType" },
                                        { "data": "StoreLocation" },                                                                                
                                        {
                                            "data": function (data) {
                                                var NetSalesLessOfVAT = CDec2(data.GrossSales) / 1.12;

                                                return AccountingFormat(NetSalesLessOfVAT);
                                            }
                                        },
                                        { "data": "TransactionCount" },                                       
                                        {
                                            "data": function (data) {
                                                var NetSalesLessOfVAT = CDec2(data.GrossSales) / 1.12;
                                                var AverageCheck = NetSalesLessOfVAT / CDec2(data.TransactionCount);

                                                return AccountingFormat(AverageCheck);  //average check
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                //var TotalDelivery = CDec2(data.FoodPanda) + CDec2(data.GrabFood) + CDec2(data.PoodTrip) + CDec2(data.DeliRush) + CDec2(data.Eatigo) + CDec2(data.Booky) + CDec2(data.Pickaroo) + CDec2(data.LocalDelivery);
                                                //var NetSalesWalkInLessOfVAT = CDec2(data.GrossSales - TotalDelivery) / 1.12;
                                                var NetSalesWalkInLessOfVAT = CDec2(data.WalkInSales) / 1.12;
                                                
                                                return AccountingFormat(NetSalesWalkInLessOfVAT); //take out/walk in sales
                                            }
                                        },
                                        {
                                            "data": function (data) {                                                
                                                //var TransactionCount = CDec2(data.TransactionCount) - CDec2(data.DeliveryCount);

                                                return CInt2(data.WalkInCount); //take out/walk in transaction count
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                //var TotalDelivery = CDec2(data.FoodPanda) + CDec2(data.GrabFood) + CDec2(data.PoodTrip) + CDec2(data.DeliRush) + CDec2(data.Eatigo) + CDec2(data.Booky) + CDec2(data.Pickaroo) + CDec2(data.LocalDelivery);
                                                //var NetSalesWalkInLessOfVAT = CDec2(data.GrossSales - TotalDelivery) / 1.12;
                                                var NetSalesWalkInLessOfVAT = CDec2(data.WalkInSales) / 1.12;
                                                
                                                var AverageCheck = NetSalesWalkInLessOfVAT / CDec2(data.WalkInCount);

                                                return AccountingFormat(AverageCheck); //average check for take out/walk in sales
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                //var TotalDelivery = CDec2(data.FoodPanda) + CDec2(data.GrabFood) + CDec2(data.PoodTrip) + CDec2(data.DeliRush) + CDec2(data.Eatigo) + CDec2(data.Booky) + CDec2(data.Pickaroo) + CDec2(data.LocalDelivery);
                                                var NetSalesDeliveryLessOfVAT = CDec2(data.DeliverySales) / 1.12;

                                                return AccountingFormat(NetSalesDeliveryLessOfVAT); //delivery aggree sales
                                            }
                                        },
                                        {
                                            "data": function (data) {                                               

                                                return CInt2(data.DeliveryCount); //delivery aggree transaction count
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                //var TotalDelivery = CDec2(data.FoodPanda) + CDec2(data.GrabFood) + CDec2(data.PoodTrip) + CDec2(data.DeliRush) + CDec2(data.Eatigo) + CDec2(data.Booky) + CDec2(data.Pickaroo) + CDec2(data.LocalDelivery);
                                                var NetSalesDeliveryLessOfVAT = CDec2(data.DeliverySales) / 1.12;

                                                var AverageCheck = NetSalesDeliveryLessOfVAT / CDec2(data.DeliveryCount)

                                                return AccountingFormat(AverageCheck); //average check for delivery aggree sales
                                            }
                                        }
                                    ],
                                    dom: 'Brtip',
                                    buttons: buttons,
                                    initComplete: function () {
                                        $('#tblSalesSummaryReport').removeClass('dataTable');
                                    },                                    
                                    footerCallback: function (row, data, start, end, display) {
                                        var api = this.api(), data;

                                        // Remove the formatting to get integer data for summation
                                        var intVal = function (i) {
                                            return typeof i === 'string' ?
                                                i.replace(/[\$,]/g, '') * 1 :
                                                typeof i === 'number' ?
                                                i : 0;
                                        };
                                        for (i = 6; i <= 14; i++) {
                                            
                                            total = api
                                                .column(i)
                                                .data()
                                                .reduce(function (a, b) {
                                                    return intVal(CDec2(a)) + intVal(CDec2(b));
                                                }, 0);
                                            
                                            // Total over this page
                                            pageTotal = api
                                                .column(i, { page: 'current' })
                                                .data()
                                                .reduce(function (a, b) {
                                                    return intVal(CDec2(a)) + intVal(CDec2(b));
                                                }, 0);

                                            // Update footer
                                            if (i == 5 || i == 8 || i == 11) {
                                                $(api.column(i).footer()).html(
                                                  CInt2(total)
                                              );
                                            } else {
                                                $(api.column(i).footer()).html(
                                                    AccountingFormat(total)
                                                );
                                            }
                                        }
                                    }
                                });

                                mSalesSummaryReport.on('click', 'td', function () {
                                    var data = mSalesSummaryReport.row(this).data();

                                });
                            }

                            //========================================== End of Sales Summary Report =====================================

