                            //========================================== ADS and ATC per Store =====================================
                            var mADSandATCperStoreReport;
                            var mADSandATCperStoreReportFrom;
                            var mADSandATCperStoreReportTo;


                            function GetADSandATCperStoreReport() {

                                if (CStr2(mSalesReportFrom) == '' || CStr2(mSalesReportTo) == '') {
                                    return;
                                }

                                if (CStr2(sessionStorage.SelectedGroup) == '') {
                                    return;
                                }

                                var data = {
                                    dateFrom: mSalesReportFrom,
                                    dateTo: mSalesReportTo,
                                    GroupID: sessionStorage.SelectedGroup,
                                    StoreType: $('#selADSandATCperStoreReportStoreType').val(),
                                    StoreLocationType: $('#selADSandATCperStoreReportStoreLocationType').val()
                                }

                                Bs.Loading('show');
                                AjaxSend({
                                    url: 'CincoCorporation/GetADSandATCperStoreReport',
                                    data: data,
                                    success: function (vData) {

                                        Bs.Loading('hide');
                                        DisplayADSandATCperStoreReport(vData.Results.Rows);

                                    }
                                });
                            }

                            function DisplayADSandATCperStoreReport(vRows) {

                                if ($.fn.DataTable.isDataTable($('#tblADSandATCperStoreReport'))) {
                                    $('#tblADSandATCperStoreReport').empty();
                                    try {
                                        mADSandATCperStoreReport.destroy();
                                    } catch (e) {

                                    }
                                }

                                var buttons = [];
                                if (!IsMobile) {
                                    buttons.push({ extend: 'csvHtml5', text: 'Download CSV', title: 'Sales Report' })
                                }

                                mADSandATCperStoreReport = $('#tblADSandATCperStoreReport').DataTable({
                                    pageLength: 25,
                                    "ordering": false,
                                    "data": vRows,
                                    "columns": [
                                        { "data": "FOWSTCode" },
                                        { "data": "FOWSTName" },
                                        { "data": "GroupName" },
                                        { "data": "StoreType" },
                                        { "data": "StoreLocation" },
                                        {
                                            "data": function (data) {
                                                //var TotalDelivery = CDec2(data.FoodPanda) + CDec2(data.GrabFood) + CDec2(data.PoodTrip) + CDec2(data.DeliRush) + CDec2(data.Eatigo) + CDec2(data.Booky) + CDec2(data.Pickaroo) + CDec2(data.LocalDelivery);
                                                //var NetSalesWalkInLessOfVAT = CDec2(data.GrossSales - TotalDelivery); /// 1.12;

                                                return AccountingFormat(CDec2(data.WalkInSales) / CDec2(data.OperatingDaysCount)); //Take Out/walk-in ADS
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                //var TotalDelivery = CDec2(data.FoodPanda) + CDec2(data.GrabFood) + CDec2(data.PoodTrip) + CDec2(data.DeliRush) + CDec2(data.Eatigo) + CDec2(data.Booky) + CDec2(data.Pickaroo) + CDec2(data.LocalDelivery);

                                                return AccountingFormat(CDec2(data.DeliverySales) / CDec2(data.OperatingDaysCount)); //Delivery ADS
                                            }
                                        },
                                        {
                                            "data": function (data) {                                               
                                                return AccountingFormat((CDec2(data.WalkInSales)+CDec2(data.DeliverySales)) / CDec2(data.OperatingDaysCount)); //BLENDED ADS
                                            }
                                        },                                        
                                        {
                                            "data": function (data) {
                                                //var TransactionCount = CDec2(data.TransactionCount) - CDec2(data.DeliveryCount);

                                                return AccountingFormat(CInt2(data.WalkInCount) / CDec2(data.OperatingDaysCount)); //Take Out ATC
                                            }
                                        },
                                        {
                                            "data": function (data) {
                                                return AccountingFormat(CInt2(data.DeliveryCount) / CDec2(data.OperatingDaysCount)); //Delivery ATC
                                            }
                                        },
                                        {
                                            "data": function (data) {                                                
                                                return AccountingFormat((CDec2(data.WalkInCount)+CDec2(data.DeliveryCount)) / CDec2(data.OperatingDaysCount)); //BLENDED ATC
                                            }
                                        }
                                    ],
                                    dom: 'Brtip',
                                    buttons: buttons,
                                    initComplete: function () {
                                        $('#tblADSandATCperStoreReport').removeClass('dataTable');
                                    }
                                    ,
                                    footerCallback: function (row, data, start, end, display) {
                                        var api = this.api(), data;

                                        // Remove the formatting to get integer data for summation
                                        var intVal = function (i) {
                                            return typeof i === 'string' ?
                                                i.replace(/[\$,]/g, '') * 1 :
                                                typeof i === 'number' ?
                                                i : 0;
                                        };
                                        for (i = 5; i <= 10; i++) {

                                            total = api
                                                .column(i)
                                                .data()
                                                .reduce(function (a, b) {
                                                    return intVal(CDec2(a)) + intVal(CDec2(b));
                                                }, 0);

                                            // Total over this page
                                            pageTotal = api
                                                .column(i, { page: 'current' })
                                                .data()
                                                .reduce(function (a, b) {
                                                    return intVal(CDec2(a)) + intVal(CDec2(b));
                                                }, 0);

                                            // Update footer
                                            $(api.column(i).footer()).html(
                                                   AccountingFormat(total)
                                               );

                                            //if (i == 5 || i == 8 || i == 11) {
                                            //    $(api.column(i).footer()).html(
                                            //      CInt2(total)
                                            //  );
                                            //} else {
                                            //    $(api.column(i).footer()).html(
                                            //        AccountingFormat(total)
                                            //    );
                                            //}
                                        }
                                    }
                                });

                                mADSandATCperStoreReport.on('click', 'td', function () {
                                    var data = mADSandATCperStoreReport.row(this).data();

                                });
                            }

