                            var mHourlySalesByWeekCategoryReport = '';
                            var mHourlySalesByWeekCategoryReportFrom = '';
                            var mHourlySalesByWeekCategoryReportTo = '';


                            function GetHourlySalesByWeekCategoryReport() {

                                if (CStr2(mSalesReportFrom) == '' || CStr2(mSalesReportTo) == '') {
                                    return;
                                }

                                if (CStr2(sessionStorage.SelectedFOWST) == '' && CStr2(sessionStorage.SelectedGroup) == '') {
                                    return;
                                }

                                var data = {
                                    dateFrom: mSalesReportFrom,
                                    dateTo: mSalesReportTo,
                                    FOWSTID: sessionStorage.SelectedFOWST,
                                    GroupID: sessionStorage.SelectedGroup
                                }

                                AjaxSend({
                                    url: 'CincoCorporation/GetHourlySalesByWeekCategoryReport',
                                    data: data,
                                    success: function (vData) {

                                        DisplayHourlySalesByWeekCategoryReport(vData.Results.Rows, vData.Results.Columns);

                                    }
                                });
                            }

                            function DisplayHourlySalesByWeekCategoryReport(vRows, vColumns) {
                                var columns = [];

                                if ($.fn.DataTable.isDataTable($('#tblDailyHourlySalesByWeekCategoryReport'))) {
                                    $('#tblDailyHourlySalesByWeekCategoryReport').empty();
                                    mHourlySalesByWeekCategoryReport.destroy();
                                }

                                var buttons = [];
                                if (!IsMobile) {
                                    buttons.push({ extend: 'csvHtml5', text: 'Download CSV', title: 'Hourly Sales By Week Category Report' })
                                }

                                //columnNames = Object.keys(vColumns);
                                //for (var i in columnNames) {
                                //    columns.push({
                                //        data: columnNames[i],
                                //        title: columnNames[i]
                                //    });
                                //}

                                //for (x = 0; x <= vRows.length - 1; x++) {
                                //    for (var i = 1; i <= columns.length - 1; i++) {
                                //        if (vRows[x][columns[i].title] == undefined) {
                                //            vRows[x][columns[i].title] = AccountingFormat(0)
                                //        } else {
                                //            vRows[x][columns[i].title] = AccountingFormat(vRows[x][columns[i].title])
                                //        }
                                //    }
                                //}


                                mHourlySalesByWeekCategoryReport = $('#tblDailyHourlySalesByWeekCategoryReport').DataTable({
                                    pageLength: 25,
                                    "ordering": false,
                                    "data": vRows,
                                    "columns": [                                       
                                       {
                                           "data": function (data) {
                                               var mHour = new Date();
                                               mHour.setHours(CInt2(data.HourOfDayInInteger));

                                               return $.format.date(mHour, 'hh:00 a');
                                               //return data.Time
                                           }
                                       },
                                       {
                                           "data": function (data) {
                                               return AccountingFormat(CDec2(data.WeekDaySales) / CInt2(data.WeekDayNoOfDays));
                                           }
                                       },
                                       {
                                           "data": function (data) {
                                               return AccountingFormat(CDec2(data.WeekEndSales) / CInt2(data.WeekEndNoOfDays));
                                           }
                                       },
                                    ],
                                    dom: 'Brtip',
                                    buttons: buttons,
                                    initComplete: function () {
                                        $('#tblDailyHourlySalesByWeekCategoryReport').removeClass('dataTable');
                                    }
                                });


                                mHourlySalesByWeekCategoryReport.on('click', 'td', function () {

                                });
                            }
                            //========================================== End of Hourly Sales By Week Category Report =====================================

                            //========================================== Daily Product Mix Report per Store  =====================================
                            var mDailyProductMixPerStoreReport = '';
                            var mDailyProductMixPerStoreReportFrom = '';
                            var mDailyProductMixPerStoreReportTo = '';


                            function GetDailyProductMixPerStoreReport() {

                                if (mDailyProductMixPerStoreReportFrom.trim() == '') {
                                    return;
                                }

                                if ((CStr2(sessionStorage.SelectedFOWST) == '' && CStr2(sessionStorage.SelectedGroup) == '') || CStr2(sessionStorage.SelectedProductID)=='') {
                                    return;
                                }

                                var data = {
                                    dateFrom: mDailyProductMixPerStoreReportFrom,
                                    dateTo: mDailyProductMixPerStoreReportTo,
                                    FOWSTID: sessionStorage.SelectedFOWST,
                                    GroupID: sessionStorage.SelectedGroup,
                                    ProductID: sessionStorage.SelectedProductID
                                }

                                Bs.Loading('show');

                                AjaxSend({
                                    url: 'CincoCorporation/GetDailyProductMixPerStoreReport',
                                    data: data,
                                    success: function (vData) {

                                        Bs.Loading('hide');
                                        DisplayDailyProductMixPerStoreReport(vData.Results.Rows, vData.Results.Columns);

                                    }
                                });
                            }

                            function DisplayDailyProductMixPerStoreReport(vRows, vColumns) {
                                var columns = [];

                                if ($.fn.DataTable.isDataTable($('#tblDailyProductMixPerStoreReport '))) {
                                    $('#tblDailyProductMixPerStoreReport ').empty();
                                    mDailyProductMixPerStoreReport.destroy();
                                }

                                var buttons = [];
                                if (!IsMobile) {
                                    buttons.push({ extend: 'csvHtml5', text: 'Download CSV', title: 'Daily Product Mix Report per Store' })
                                }

                                mDailyProductMixPerStoreReport = $('#tblDailyProductMixPerStoreReport').DataTable({
                                    pageLength: 25,
                                    "ordering": false,
                                    "data": vRows,
                                    "columns": [                 
                                        { "data": "FOWSTCode" },
                                        { "data": "FowstName" },
                                        {
                                            "data": function (data) {
                                                if(CInt2(data.Ownership)>0){
                                                    return 'Franchised'
                                                }else{
                                                    return 'Company-Owned'
                                                }
                                            }
                                        },
                                       { "data": "GroupName" },
                                       { "data": "StoreLocation" },
                                       { "data": "ProductName" },
                                       {
                                           "data": function (data) {
                                               return AccountingFormat(data.TotalSales);
                                           }
                                       },
                                       {
                                           "data": function (data) {
                                               return CInt2(data.QtySold);
                                           }
                                       },                                    
                                       {
                                           "data": function (data) {
                                               return CInt2(data.OperatingDays);
                                           }
                                       },
                                       {
                                           "data": function (data) {
                                               if(CInt2(data.OperatingDays)>0){
                                                   return AccountingFormat(CInt2(data.QtySold) / CInt2(data.OperatingDays));
                                               }else
                                               {
                                                   return '-';
                                               }
                                               
                                           }
                                       }
                                    ],
                                    dom: 'Brtip',
                                    buttons: buttons,
                                    initComplete: function () {
                                        $('#tblDailyProductMixPerStoreReport').removeClass('dataTable');
                                    }
                                });


                                mDailyProductMixPerStoreReport.on('click', 'td', function () {

                                });
                            }
                            //========================================== End of Daily Product Mix Report  per Store =====================================

