                            var mWeeklySalesReportDateFrom;
                            var mWeeklySalesReportDateTo;
                            var mWeeklySalesReport;
                            var mFourWeeklySalesReports;

                            function SetReportWeeksAndYear(){
                                var selWeeklySalesReportWeek = $('#selWeeklySalesReportWeek')
                                var selWeeklySalesReportYear = $('#selWeeklySalesReportYear')

                                for(i=0;i<52;i++){
                                    if(i==0)
                                        selWeeklySalesReportWeek.append(new Option('Week ' + (i+1), (i+1), true, true)); 
                                    else
                                        selWeeklySalesReportWeek.append(new Option('Week ' + (i+1), (i+1), false, false)); 
                                }

                                for(i=0;i<3;i++){
                                    if(i==0)
                                        selWeeklySalesReportYear.append(new Option('Year ' + ((new Date).getFullYear() - i), ((new Date).getFullYear() - i), true, true)); 
                                    else
                                        selWeeklySalesReportYear.append(new Option('Year ' + ((new Date).getFullYear() - i), ((new Date).getFullYear() - i), false, false)); 
                                }

                                ComputeDateRange();
                            }

                            function ComputeDateRange(){
                                var WeekNo = CInt2($('#selWeeklySalesReportWeek').val());
                                var YearNo = CInt2($('#selWeeklySalesReportYear').val());

                                var computedDate = new Date(YearNo, 0, 1);
                                var computedDate1 = new Date('1/1/' + YearNo);
                                var computedDate2 = new Date('1/1/' + YearNo);

                                computedDate1.setFullYear(YearNo);
                                computedDate2.setFullYear(YearNo);

                                computedDate1.setDate(computedDate.getDate() + ((WeekNo-1) * 7));
                                computedDate2.setDate(computedDate.getDate() + ((WeekNo-1) * 7));

                                mWeeklySalesReportDateFrom = computedDate1;
                                mWeeklySalesReportDateTo = new Date(computedDate2.setDate(computedDate2.getDate() + 6));
                                $('.lblWeeklySalesReportDateRange').text( $.format.date(mWeeklySalesReportDateFrom, 'MMM d yyyy') + '-' + $.format.date(mWeeklySalesReportDateTo, 'MMM d yyyy'));

                            }

