                            //========================================== Weekly ADS Report =====================================
                            var mWeeklyADSReportDateFrom;
                            var mWeeklyADSReportDateTo;
                            var mWeeklyADSReport;
                            var mFourWeeklyADSReports;

                            function SetReportADSWeeksAndYear(){
                                var selWeeklySalesReportWeek = $('#selWeeklyAverageDailySalesReportWeek')
                                var selWeeklySalesReportYear = $('#selWeeklyAverageDailySalesReportYear')

                                selWeeklySalesReportWeek.empty();
                                selWeeklySalesReportYear.empty();

                                for(i=0;i<52;i++){
                                    if(i==0)
                                        selWeeklySalesReportWeek.append(new Option('Week ' + (i+1), (i+1), true, true)); 
                                    else
                                        selWeeklySalesReportWeek.append(new Option('Week ' + (i+1), (i+1), false, false)); 
                                }

                                for(i=0;i<3;i++){
                                    if(i==0)
                                        selWeeklySalesReportYear.append(new Option('Year ' + ((new Date).getFullYear() - i), ((new Date).getFullYear() - i), true, true)); 
                                    else
                                        selWeeklySalesReportYear.append(new Option('Year ' + ((new Date).getFullYear() - i), ((new Date).getFullYear() - i), false, false)); 
                                }

                                ComputeADSDateRange();
                            }

                            function ComputeADSDateRange(){
                                var WeekNo = CInt2($('#selWeeklyAverageDailySalesReportWeek').val());
                                var YearNo = CInt2($('#selWeeklyAverageDailySalesReportYear').val());

                                var computedDate = new Date(YearNo, 0, 1);
                                var computedDate1 = new Date('1/1/' + YearNo);
                                var computedDate2 = new Date('1/1/' + YearNo);

                                computedDate1.setFullYear(YearNo);
                                computedDate2.setFullYear(YearNo);

                                computedDate1.setDate(computedDate.getDate() + ((WeekNo-1) * 7));
                                computedDate2.setDate(computedDate.getDate() + ((WeekNo-1) * 7));

                                mWeeklyADSReportDateFrom = computedDate1;
                                mWeeklyADSReportDateTo = new Date(computedDate2.setDate(computedDate2.getDate() + 6));
                                $('.lblWeeklyAverageDailySalesReportDateRange').text( $.format.date(mWeeklyADSReportDateFrom, 'MMM d yyyy') + '-' + $.format.date(mWeeklyADSReportDateTo, 'MMM d yyyy'));

                            }

                            function GetWeeklyAverageDailySalesReport(){
                                var data = {
                                    dateFrom: mWeeklyADSReportDateFrom,
                                    dateTo: mWeeklyADSReportDateTo,
                                    WeekNo: CInt2($('#selWeeklyAverageDailySalesReportWeek').val())
                                }
                                
                                Bs.Loading('show');
                                AjaxSend({
                                    url: 'CincoCorporation/GetFourWeeklyAverageDailySalesReports',
                                    data: data,
                                    timeout: 60000,
                                    success: function (vData) {

                                        Bs.Loading('hide');
                                        DisplayFourWeeklyADSReports(vData);

                                    }
                                });
                            }


                            function DisplayFourWeeklyADSReports(vData){                                
                                var columns = [];
                                var buttons = [];

                                if ($.fn.DataTable.isDataTable($('#tblFourWeeksADSReport'))) {
                                    $('#tblFourWeeksADSReport').empty();
                                    mFourWeeklyADSReports.destroy();
                                }
                                
                                if (!IsMobile) {
                                    buttons.push({ extend: 'csvHtml5', text: 'Download CSV', title: 'Four Weeks Sales Report' })
                                }

                                var columnNames = Object.keys(vData.MainTable.Columns);

                                for (var i in columnNames) {
                                    columns.push({
                                        data: columnNames[i],
                                        title: columnNames[i]                                        
                                    });
                                }


                                mFourWeeklyADSReports = $('#tblFourWeeksADSReport').DataTable({                                    
                                    columns: columns,
                                    "data": vData.MainTable.Rows,
                                    "ordering": false,
                                    iDisplayLength: -1,
                                    buttons: buttons,
                                    dom: 'Bfrtip'
                                });
                            }

