                            var mSalesPaymentInformationReport = '';
                            var mSalesPaymentInformationReportFrom = '';
                            var mSalesPaymentInformationReportTo = '';


                            function GetSalesPaymentInformationReport() {

                                if (mSalesPaymentInformationReportFrom.trim() == '') {
                                    return;
                                }

                                if (CStr2(sessionStorage.SelectedMultipleFOWST) == '' && CStr2(sessionStorage.SelectedGroup) == '') {
                                    return;
                                }

                                var data = {
                                    dateFrom: mSalesPaymentInformationReportFrom,
                                    dateTo: mSalesPaymentInformationReportTo,
                                    FOWSTID: sessionStorage.SelectedMultipleFOWST,
                                    GroupID: sessionStorage.SelectedGroup
                                }

                                Bs.Loading('show');
                                
                                AjaxSend({
                                    url: 'CincoCorporation/GetSalesPaymentInformationReport',
                                    data: data,
                                    success: function (vData) {

                                        Bs.Loading('hide');
                                        DisplaySalesPaymentInformationReport(vData.Results.Rows, vData.Results.Columns);

                                    }
                                });
                            }

                            function DisplaySalesPaymentInformationReport(vRows, vColumns) {
                                var columns = [];

                                if ($.fn.DataTable.isDataTable($('#tblSalesPaymentInformationReport'))) {
                                    $('#tblSalesPaymentInformationReport').empty();
                                    mSalesPaymentInformationReport.destroy();
                                }

                                var buttons = [];
                                if (!IsMobile) {
                                    buttons.push({ extend: 'csvHtml5', text: 'Download CSV', title: 'Sales Payment Information Report' })
                                }
                                
                                mSalesPaymentInformationReport = $('#tblSalesPaymentInformationReport').DataTable({
                                    pageLength: 25,
                                    "data": vRows,
                                    "columns": [
                                        { "data": "FOWSTName" },
                                       {
                                           "data": function (data) {
                                               return $.format.date(new Date(data.TransactionDate), 'MMM d, yyyy hh:mm a');
                                           }
                                       },                                       
                                        {
                                            "data": null, createdCell: function (td, cellData, rowData, row, col) {
                                                if (rowData.InvoiceNumber != '0') {
                                                    var btn = $('<a href="#">').text($.format.number(CDec2(rowData.InvoiceNumber), '000000000000'));
                                                    $(td).data('data', rowData).css('text-align', 'center').html(btn)
                                                        .click(function () {
                                                            var data = $(this).data('data');

                                                            GetInvoiceDetails(data.InvoiceID);
                                                        })
                                                } else $(td).text('')
                                            }, className: 'text-center'
                                        },
                                       { "data": "PaymentType" },                                       
                                        {
                                            "data": function (data) {
                                                return AccountingFormat(data.Amount)
                                            }
                                        },
                                       { 
                                           "data": function (data) {
                                               if(data.PaymentType=='GCash'){                                                   
                                                   return ('000000000' + data.GCashRefNo).substr(-9);
                                               }else{
                                                   return data.GCashRefNo
                                               }
                                               
                                           }
                                       }
                                    ],
                                    dom: 'Brtip',
                                    buttons: buttons,
                                    initComplete: function () {
                                        $('#tblSalesPaymentInformationReport').removeClass('dataTable');
                                    }
                                });


                                mSalesPaymentInformationReport.on('click', 'td', function () {

                                });
                            }
