                            function GetPageAccess() {
                                var mdata = {
                                    OrgID: sessionStorage.OrgID
                                }

                                var m_Date = new Date();

                                data = {
                                    GroupBy: 'All',
                                    FowstID: 'All',
                                    From: (m_Date.getMonth() + 1) + '/' + m_Date.getDate() + '/' + m_Date.getFullYear(), //change the month, copy the 'To' Month
                                    To: (m_Date.getMonth() + 1) + '/' + m_Date.getDate() + '/' + m_Date.getFullYear(),
                                    IsRawData: 0
                                }
                                GetOrganizationName();
                                AjaxSend({
                                    url: 'DashboardsAndReports/GetPageAccess',
                                    data: mdata,
                                    success: function (vData) {
                                        if (CBool(vData.Results)) {
                                            sessionStorage.IsShowFirstPage = 'true'; //TODO
                                            sessionStorage.IsFromDashboardPage = true;

                                            GetTotalGrossAndDiscounts();
                                            GetFOWSTCount();

                                            data.GroupBy = 'ByOrganizationGroup';
                                            //GetTotalGrossAndDiscountsByGROUP();
                                            //GetPageAccess();
                                        } else {
                                            sessionStorage.IsShowFirstPage = 'false';

                                            $('#divMainDashboard').hide();
                                            TempValueBtnBack = 'BackToDashboard';

                                            $('#divSalesAnalytics').fadeIn('fast', function () {
                                                var ns = $('#NetSalesHeight').height();
                                                var gs = $('#GrossSalesHeight').height();
                                                var et = $('#ExtrasTotalHeight').height();

                                                if ($(window).width() >= 576) {
                                                    if (ns > gs) {
                                                        $('#GrossSalesHeight, #ExtrasTotalHeight').css('height', ns);
                                                    } else if (ns < gs) {
                                                        $('#NetSalesHeight, #ExtrasTotalHeight').css('height', gs);
                                                    } else if (et > ns || et > gs) {
                                                        $('#NetSalesHeight, #GrossSalesHeight').css('height', et);
                                                    } else if (ns == gs) {
                                                        $('#NetSalesHeight, #ExtrasTotalHeight').css('height', gs);
                                                    }
                                                } else {
                                                    $('#NetSalesHeight, #GrossSalesHeight, #ExtrasTotalHeight').css('height', 'auto');
                                                }
                                            });

                                            GetTotalGrossAndDiscountsByFOWST();
                                        }
                                    }
                                });
                            }

                            function GetAverageDailySales() {
                                var mdata = {
                                    dateFrom: data.From,
                                    dateTo: data.To
                                }

                                if (data == undefined) {
                                    var m_Date = new Date();

                                    mdata.dateFrom = (m_Date.getMonth() + 1) + '/' + m_Date.getDate() + '/' + m_Date.getFullYear()
                                    mdata.dateTo = (m_Date.getMonth() + 1) + '/' + m_Date.getDate() + '/' + m_Date.getFullYear()
                                }


                                AjaxSend({
                                    url: 'CincoCorporation/GetAverageDailySales',
                                    data: mdata,
                                    success: function (vData) {
                                        if (vData.Results.Rows.length > 0) {

                                            var pData = [];

                                            for (var i = 0; i <= vData.Results.Rows.length - 1; i++) {
                                                var vRows = {};
                                                var mData = [];

                                                mData[0] = vData.Results.Rows[i].Monday;
                                                mData[1] = vData.Results.Rows[i].Tuesday;
                                                mData[2] = vData.Results.Rows[i].Wednesday;
                                                mData[3] = vData.Results.Rows[i].Thursday;
                                                mData[4] = vData.Results.Rows[i].Friday;
                                                mData[5] = vData.Results.Rows[i].Saturday;
                                                mData[6] = vData.Results.Rows[i].Sunday;

                                                vRows.label = $.format.date(new Date(vData.Results.Rows[i].DateTo), 'MMM d yyyy');
                                                vRows.type = 'bar';

                                                vRows.data = mData;

                                                if (i == 0)
                                                    vRows.backgroundColor = "#eece01";
                                                if (i == 1)
                                                    vRows.backgroundColor = "#f8981f";
                                                if (i == 2)
                                                    vRows.backgroundColor = "#87d84d";
                                                if (i == 3)
                                                    vRows.backgroundColor = "#00b300";

                                                pData.push(vRows);
                                            }

                                            DisplayADSChart(pData)
                                        }
                                    }
                                });
                            }

                            window.GetTopRankingStores = function(IsGroupStore, date) {
                                var mdata = {
                                    dateFrom: (date == undefined ? data.From : date.From),
                                    dateTo: (date == undefined ? data.To : date.To),
                                    IsTop: 1,
                                    IsGroupStore: IsGroupStore,
                                    GroupFOWSTID: sessionStorage.SelectedGroup
                                }

                                AjaxSend({
                                    url: 'CincoCorporation/GetTopAndBottomRankingStores',
                                    data: mdata,
                                    success: function (vData) {
                                        if (IsGroupStore) {
                                            DisplayTopRankingStoresInGroup(vData.ASC.Rows);
                                            DisplayBottomRankingStoresInGroup(vData.DESC.Rows);
                                        } else {
                                            DisplayTopRankingStores(vData.ASC.Rows);
                                            DisplayBottomRankingStores(vData.DESC.Rows);
                                        }

                                        GetAverageDailySales();
                                    }
                                });
                            }

